/**
 * Types for the viewer data bundle generated by scripts/build-data.mjs
 * from data/listings.jsonl + data/categories.json.
 *
 * Field semantics are uniform across the module:
 * - Scalars that are absent in the source are `null` — never 0, never "",
 *   never invented.
 * - Collections that are empty/absent in the source are empty arrays.
 * - `stars` is the numeric GitHub star count or `null` when the source
 *   shows none. `starsApproximate` is `true` when the number was parsed
 *   from a rounded source string (e.g. "1.3K" → 1300), `false` when exact,
 *   and `null` when there is no star data at all.
 */

export type Deployment = 'Cloud' | 'Self-hosted' | 'Local';

/** Flat matrix-row fields — everything the spec-matrix table needs. */
export interface MatrixRow {
  /** Listing slug, identical to the final path segment of the githits URL. */
  id: string;
  name: string;
  summary: string;
  /** Display name, e.g. "Agent orchestration". */
  category: string;
  /** Machine category key, e.g. "agent-orchestration". */
  categorySlug: string;
  /** SPDX-style license id from the License details entry (e.g. "MIT"). */
  license: string | null;
  /** Deployment tokens in source order, split from the details entry. */
  deployment: Array<Deployment> | null;
  /** true = open source, false = proprietary, null = unspecified. */
  oss: boolean | null;
  stars: number | null;
  starsApproximate: boolean | null;
  /** Topic display names, e.g. "Enterprise". Empty when untagged. */
  topics: Array<string>;
}

export interface EntryLink {
  text: string;
  href: string;
}

export interface TopicRef {
  text: string;
  url: string;
}

export interface EntryTime {
  text: string;
  datetime: string;
}

export interface RepositoryRef {
  /** Display text, e.g. "github.com/aeonfun/aeon". */
  text: string;
  url: string;
  stars: number | null;
  starsApproximate: boolean | null;
}

/**
 * One row of the source page's details section, mirrored in source order.
 * `text` is the rendered text of the entry (star counts included, e.g.
 * "github.com/aeonfun/aeon · 777 stars"); optional keys appear only on the
 * labels that carry them in the source ("Topics" → topics,
 * "Last verified" → time, "Repository" → repositories).
 */
export interface DetailEntry {
  label: string;
  text: string;
  links: Array<EntryLink>;
  topics?: Array<TopicRef>;
  time?: EntryTime;
  repositories?: Array<RepositoryRef>;
}

export interface SimilarItem {
  name: string;
  url: string;
  /** Category display name as rendered on the similar card. */
  category: string;
  summary: string;
  logoUrl: string | null;
  /** Badge texts as rendered on the card, e.g. ["Open source"]. */
  badges: Array<string>;
  stars: number | null;
  starsApproximate: boolean | null;
}

export interface SourceSnapshot {
  requestedUrl: string;
  finalUrl: string;
  fetchedAt: string;
  status: number;
  bodySha256: string;
  /** Path of the HTML snapshot inside the scraper cache (data/cache). */
  snapshotPath: string;
}

/** Full per-record detail payload for the drawer. */
export interface ListingDetail {
  /** Overview paragraph texts in source order. */
  overview: Array<string>;
  /** Feature bullet texts in source order. */
  features: Array<string>;
  /** Details entries mirrored in source order. */
  entries: Array<DetailEntry>;
  similar: {
    items: Array<SimilarItem>;
    moreLink: { text: string; url: string };
  };
  logoUrl: string | null;
  /** Canonical githits.com listing URL this record was scraped from. */
  sourceUrl: string;
  snapshot: SourceSnapshot;
}

export interface Listing extends MatrixRow {
  detail: ListingDetail;
}

export interface CategoryInfo {
  slug: string;
  /** Display name, e.g. "Code review & quality". */
  name: string;
  /** githits.com category page URL. */
  url: string;
  /** Number of bundle records in this category. */
  count: number;
}
